{
  "utils.marketo__calendar_spine": {
    "items": [
      {
        "problem": "The calendar's end date is assumed to be today even though no visible utility specification establishes that bound.",
        "about": "data",
        "evidence_in_work": "CURRENT_DATE AS max_date",
        "source": "The upper bound of dates is defined only by the calendar spine; no additional end-date filter is applied.",
        "importance": 2,
        "reason": "An incorrect utility range changes the coverage of every downstream lead calendar."
      }
    ],
    "fewer_reason": "No detailed utility contract is provided, so additional range assumptions cannot be assessed reliably."
  },
  "staging.stg_marketo__lead": {
    "items": [
      {
        "problem": "Non-normalized emails are corrected and retained rather than deleted as the field-specific failure action requires.",
        "about": "requirement",
        "evidence_in_work": "LOWER(TRIM(email)) AS email",
        "source": "rule: \"email = LOWER(TRIM(email))\" ... on_failure: delete_row",
        "importance": 4,
        "reason": "This changes which leads enter every downstream lead model."
      },
      {
        "problem": "Duplicate lead IDs are resolved using textual updated_at ordering, which may not select the chronologically latest record when formats or offsets differ.",
        "about": "data",
        "evidence_in_work": "PARTITION BY id ORDER BY updated_at DESC NULLS LAST",
        "source": "updated_timestamp ... data_type: VARCHAR",
        "importance": 2,
        "reason": "Incorrect survivor selection would propagate stale profile attributes."
      }
    ],
    "fewer_reason": "The final edits handle nullable names and the visible required columns; no further independent material problems are supported."
  },
