        "importance": 3,
        "reason": "An extra backslash in the emitted DuckDB regex could remove sender addresses across the entire table."
      },
      {
        "problem": "Template-version uniqueness is not enforced or tested.",
        "about": "data",
        "evidence_in_work": "FROM raw.marketo_email_template_history",
        "source": "grain: \"One row per email template version\"",
        "importance": 2,
        "reason": "Duplicate versions can multiply send fact rows when history is joined by template ID."
